const CHECK = /^export function (\w+)\([^)]*\): (?:boolean|\w+ is )/gm;
const TEST_NAME = /\btest\(\s*(['`])(.*?)\1/gs;
const REQUIREMENT_ID = /\b[A-Z]\d{2}\b/;
